      await waitFor(() => expect(screen.getByText("Active project beta")).toBeInTheDocument());
      await waitFor(() => expect(workspace.ensureTabForWorktree).toHaveBeenCalledWith(betaDocs));
    } finally {
      workspace.storeState.worktrees.length = 4;
    }
  });

