    fireEvent.keyDown(window, { key: "4", ctrlKey: true });
    expect(workspace.ensureTabForWorktree).toHaveBeenCalledWith(workspace.storeState.worktrees[3]);

    // Out of range (index 5) or unmodified number typing is harmless
