import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import {
  createSession,
  flushAnimationFrames,
  mocks,
  setupTerminalHostTestEnv,
} from "./terminalHostManagerTestHelper";
import { terminalEventBus } from "./terminalEvents";
import { MAX_PENDING_OUTPUT_CHARS, terminalHostManager } from "./terminalHostManager";

describe("terminalHostManager output scheduling & batching", () => {
  beforeEach(() => {
    setupTerminalHostTestEnv();
  });

  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it("unsubscribes previous backendSessionId output subscription when backendSessionId changes in updateSession", async () => {
    const session = createSession("sess-update", "backend-old");
    const unreg = terminalHostManager.registerVisible("sess-update");
    await terminalHostManager.getOrCreate(session, true);

    mocks.terminalWrites.length = 0;
    mocks.emitSessionOutput("backend-old", "hello old");
    flushAnimationFrames();
    expect(mocks.terminalWrites).toContain("hello old");

    mocks.terminalWrites.length = 0;
    const updatedSession = createSession("sess-update", "backend-new");
    terminalHostManager.updateSession("sess-update", updatedSession);

    // Old backend session output must NOT be written anymore
    mocks.emitSessionOutput("backend-old", "old after update");
    flushAnimationFrames();
    expect(mocks.terminalWrites).not.toContain("old after update");

    // New backend session output MUST be written
    mocks.emitSessionOutput("backend-new", "hello new");
    flushAnimationFrames();
    expect(mocks.terminalWrites).toContain("hello new");

    unreg();
    terminalHostManager.destroy("sess-update");
  });

  it("batches same-frame output writes at animation-frame cadence into a single ordered terminal write", async () => {
    const session = createSession("sess-batched", "backend-batch");
    const unreg = terminalHostManager.registerVisible("sess-batched");
    await terminalHostManager.getOrCreate(session, true);

    mocks.terminalWrites.length = 0;

    mocks.emitSessionOutput("backend-batch", "chunk1-");
    mocks.emitSessionOutput("backend-batch", "chunk2-");
    mocks.emitSessionOutput("backend-batch", "chunk3");

    // Zero immediate writes before frame flush
    expect(mocks.terminalWrites).toHaveLength(0);

    // Flush animation frame
    flushAnimationFrames();

    // Exactly one write call with all 3 chunks in original order
    expect(mocks.terminalWrites).toEqual(["chunk1-chunk2-chunk3"]);

    unreg();
    terminalHostManager.destroy("sess-batched");
  });

  it("cancels pending batched output and prevents writes after destroy or updateSession rebinding", async () => {
    // 1. Teardown via destroy
    const session1 = createSession("sess-teardown-1", "backend-td-1");
    const unreg1 = terminalHostManager.registerVisible("sess-teardown-1");
    await terminalHostManager.getOrCreate(session1, true);
    mocks.terminalWrites.length = 0;

    mocks.emitSessionOutput("backend-td-1", "pending before destroy");
    unreg1();
    terminalHostManager.destroy("sess-teardown-1");

    flushAnimationFrames();
    expect(mocks.terminalWrites).toHaveLength(0);

    // 2. Teardown via updateSession rebinding
    const session2 = createSession("sess-teardown-2", "backend-td-old");
    const unreg2 = terminalHostManager.registerVisible("sess-teardown-2");
    await terminalHostManager.getOrCreate(session2, true);
    mocks.terminalWrites.length = 0;

    mocks.emitSessionOutput("backend-td-old", "pending before rebind");
    const session2Updated = createSession("sess-teardown-2", "backend-td-new");
    terminalHostManager.updateSession("sess-teardown-2", session2Updated);

    flushAnimationFrames();
    expect(mocks.terminalWrites).toHaveLength(0);

    // New backend emits and flushes normally
    mocks.emitSessionOutput("backend-td-new", "live new");
    expect(mocks.terminalWrites).toHaveLength(0);
    flushAnimationFrames();
    expect(mocks.terminalWrites).toEqual(["live new"]);

    unreg2();
    terminalHostManager.destroy("sess-teardown-2");
  });

  it("batches outputs per session independently without cross-session mixing", async () => {
    const session1 = createSession("sess-mix-1", "backend-mix-1");
    const session2 = createSession("sess-mix-2", "backend-mix-2");

    const unreg1 = terminalHostManager.registerVisible("sess-mix-1");
    const unreg2 = terminalHostManager.registerVisible("sess-mix-2");

    await terminalHostManager.getOrCreate(session1, true);
    await terminalHostManager.getOrCreate(session2, true);

    mocks.terminalWrites.length = 0;

    mocks.emitSessionOutput("backend-mix-1", "s1-a");
    mocks.emitSessionOutput("backend-mix-2", "s2-a");
    mocks.emitSessionOutput("backend-mix-1", "s1-b");
    mocks.emitSessionOutput("backend-mix-2", "s2-b");

    expect(mocks.terminalWrites).toHaveLength(0);

    flushAnimationFrames();

    expect(mocks.terminalWrites).toEqual(["s1-as1-b", "s2-as2-b"]);

    unreg1();
    unreg2();
    terminalHostManager.destroy("sess-mix-1");
    terminalHostManager.destroy("sess-mix-2");
  });

  it("maintains replay-before-live ordering on initial subscription", async () => {
    const session = createSession("sess-replay", "backend-replay");
    const unreg = terminalHostManager.registerVisible("sess-replay");

    // Simulate backlog replay synchronously during subscribeOutput
    vi.spyOn(terminalEventBus, "subscribeOutput").mockImplementationOnce((sessionId: string, cb: (text: string) => void) => {
      let set = mocks.outputListeners.get(sessionId);
      if (!set) {
        set = new Set();
        mocks.outputListeners.set(sessionId, set);
      }
      set.add(cb);
      cb("replay-chunk-");
      return vi.fn(() => {
        set?.delete(cb);
        if (set?.size === 0) mocks.outputListeners.delete(sessionId);
      });
    });

    await terminalHostManager.getOrCreate(session, true);
    mocks.emitSessionOutput("backend-replay", "live-chunk");

    // Clear preview banner writes
    mocks.terminalWrites.length = 0;

    // Zero immediate writes before frame flush
    expect(mocks.terminalWrites).toHaveLength(0);

    flushAnimationFrames();
    expect(mocks.terminalWrites).toEqual(["replay-chunk-live-chunk"]);

    unreg();
    terminalHostManager.destroy("sess-replay");
  });

  it("synchronously flushes pending output when accumulated characters reach or exceed MAX_PENDING_OUTPUT_CHARS before rAF", async () => {
    const session = createSession("sess-cap", "backend-cap");
    const unreg = terminalHostManager.registerVisible("sess-cap");
    await terminalHostManager.getOrCreate(session, true);

    mocks.terminalWrites.length = 0;

    const halfCap = "A".repeat(MAX_PENDING_OUTPUT_CHARS / 2);
    const exceedCap = "B".repeat(MAX_PENDING_OUTPUT_CHARS / 2 + 10);
    const trailingChunk = "C".repeat(50);

    // 1. Below cap: queued without immediate write
    mocks.emitSessionOutput("backend-cap", halfCap);
    expect(mocks.terminalWrites).toHaveLength(0);

    // 2. Reaching/exceeding cap: synchronously flushes accumulated batch immediately before rAF
    mocks.emitSessionOutput("backend-cap", exceedCap);
    expect(mocks.terminalWrites).toEqual([halfCap + exceedCap]);

    // 3. New chunk arriving after flush is held for next rAF
    mocks.emitSessionOutput("backend-cap", trailingChunk);
    expect(mocks.terminalWrites).toEqual([halfCap + exceedCap]);

    // 4. On rAF flush, trailing chunk is written in ordered sequence
    flushAnimationFrames();
    expect(mocks.terminalWrites).toEqual([halfCap + exceedCap, trailingChunk]);

    unreg();
    terminalHostManager.destroy("sess-cap");
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import {
  createDeferred,
  createSession,
  mocks,
  setupTerminalHostTestEnv,
} from "./terminalHostManagerTestHelper";
import { terminalHostManager } from "./terminalHostManager";
import * as terminalSettings from "./terminalSettings";

describe("terminalHostManager core lifecycle & race conditions", () => {
  beforeEach(() => {
    setupTerminalHostTestEnv();
  });

  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it("renders Ferryx branding in non-Tauri preview banner", async () => {
    const session = createSession("sess-banner");
    await terminalHostManager.getOrCreate(session, true);

    const bannerText = mocks.terminalWrites.join("");
    expect(bannerText).toContain("Ferryx");
    expect(bannerText).not.toContain("rorca");
    terminalHostManager.destroy("sess-banner");
  });

  it("fires onBell and onTitleChange exactly once and does not fire stale initial closures when cleared", async () => {
    const session = createSession("sess-events");
    const onBell1 = vi.fn();
    const onTitle1 = vi.fn();

    await terminalHostManager.getOrCreate(session, true, onBell1, onTitle1);

    mocks.triggerBell();
    expect(onBell1).toHaveBeenCalledTimes(1);

    mocks.triggerTitleChange("new title 1");
    expect(onTitle1).toHaveBeenCalledTimes(1);
    expect(onTitle1).toHaveBeenCalledWith("new title 1");

    // Re-register with new callbacks (e.g. component re-render)
    const onBell2 = vi.fn();
    const onTitle2 = vi.fn();
    await terminalHostManager.getOrCreate(session, true, onBell2, onTitle2);

    mocks.triggerBell();
    expect(onBell1).toHaveBeenCalledTimes(1); // Should not fire stale callback
    expect(onBell2).toHaveBeenCalledTimes(1);

    mocks.triggerTitleChange("new title 2");
    expect(onTitle1).toHaveBeenCalledTimes(1); // Should not fire stale callback
    expect(onTitle2).toHaveBeenCalledTimes(1);
    expect(onTitle2).toHaveBeenCalledWith("new title 2");

    // When cleared, neither stale callback should fire
    await terminalHostManager.getOrCreate(session, true, undefined, undefined);
    mocks.triggerBell();
    expect(onBell1).toHaveBeenCalledTimes(1);
    expect(onBell2).toHaveBeenCalledTimes(1);

    mocks.triggerTitleChange("new title 3");
    expect(onTitle1).toHaveBeenCalledTimes(1);
    expect(onTitle2).toHaveBeenCalledTimes(1);

    terminalHostManager.destroy("sess-events");
  });

  it("integrates search addon into terminal instance and disposes it on destroy", async () => {
    const session = createSession("sess-search");
    const unreg = terminalHostManager.registerVisible("sess-search");
    const instance = await terminalHostManager.getOrCreate(session, true);

    expect(instance.searchAddon).toBeDefined();
    expect(instance.terminal.loadAddon).toHaveBeenCalledWith(instance.searchAddon);

    unreg();
    terminalHostManager.destroy("sess-search");
    expect(mocks.searchAddonDisposed).toHaveBeenCalledTimes(1);
  });

  it("disposes stale renderer and does not resurrect instances or LRU when destroy occurs during pending creation", async () => {
    const deferredPrefs = createDeferred<typeof terminalSettings.FALLBACK_PREFERENCES>();
    const prefsSpy = vi.spyOn(terminalSettings, "fetchCachedNativePreferences").mockImplementation(() => deferredPrefs.promise);

    const session = createSession("sess-race-destroy", "backend-race-destroy");

    try {
      // 1. Initiate getOrCreate while preference resolution (renderer creation) is pending
      const pendingCreation = terminalHostManager.getOrCreate(session, true);

      // 2. Destroy session while creation is awaiting
      terminalHostManager.destroy("sess-race-destroy");

      // Verify not yet in instances
      expect(terminalHostManager.getInstance("sess-race-destroy")).toBeUndefined();

      // 3. Resolve the delayed creation promise
      deferredPrefs.resolve(terminalSettings.FALLBACK_PREFERENCES);
      const staleInstance = await pendingCreation;

      // 4. Stale instance must be disposed and not populate instances or cache
      expect(terminalHostManager.getInstance("sess-race-destroy")).toBeUndefined();
      expect(mocks.terminalDisposed).toHaveBeenCalledTimes(1);
      expect(mocks.searchAddonDisposed).toHaveBeenCalledTimes(1);

      // 5. Subsequent legitimate getOrCreate for the same session ID succeeds with a fresh instance
      prefsSpy.mockResolvedValue(terminalSettings.FALLBACK_PREFERENCES);
      const freshInstance = await terminalHostManager.getOrCreate(session, true);
      expect(freshInstance).toBeDefined();
      expect(freshInstance).not.toBe(staleInstance);
      expect(terminalHostManager.getInstance("sess-race-destroy")).toBe(freshInstance);
    } finally {
      prefsSpy.mockRestore();
      terminalHostManager.destroy("sess-race-destroy");
    }
  });

  it("handles overlapping destroy and new getOrCreate before stale creation resolves without erasing newer pending creation", async () => {
    const deferredPrefs1 = createDeferred<typeof terminalSettings.FALLBACK_PREFERENCES>();
    const deferredPrefs2 = createDeferred<typeof terminalSettings.FALLBACK_PREFERENCES>();

    const prefsSpy = vi.spyOn(terminalSettings, "fetchCachedNativePreferences")
      .mockImplementationOnce(() => deferredPrefs1.promise)
      .mockImplementationOnce(() => deferredPrefs2.promise);

    const session = createSession("sess-overlap-destroy", "backend-overlap-destroy");

    try {
      // 1. Initiate first getOrCreate
      const firstCreation = terminalHostManager.getOrCreate(session, true);

      // 2. Destroy session while first creation is pending
      terminalHostManager.destroy("sess-overlap-destroy");

      // 3. Initiate second getOrCreate before first creation resolves
      const secondCreation = terminalHostManager.getOrCreate(session, true);

      // 4. Resolve first (stale) creation
      deferredPrefs1.resolve(terminalSettings.FALLBACK_PREFERENCES);
      const staleInstance = await firstCreation;

      // Stale instance must be disposed, not in instances
      expect(terminalHostManager.getInstance("sess-overlap-destroy")).toBeUndefined();
      expect(mocks.terminalDisposed).toHaveBeenCalled();

      // 5. Resolve second (legitimate) creation
      deferredPrefs2.resolve(terminalSettings.FALLBACK_PREFERENCES);
      const newInstance = await secondCreation;

      expect(newInstance).toBeDefined();
      expect(newInstance).not.toBe(staleInstance);
      expect(terminalHostManager.getInstance("sess-overlap-destroy")).toBe(newInstance);
    } finally {
      prefsSpy.mockRestore();
      terminalHostManager.destroy("sess-overlap-destroy");
    }
  });
});

import { describe, expect, it, vi } from "vitest";

import type { TerminalLifecyclePayload, TerminalOutputPayload } from "./types";

const callbacks = vi.hoisted(() => ({
  output: null as ((payload: TerminalOutputPayload) => void) | null,
  lifecycle: null as ((payload: TerminalLifecyclePayload) => void) | null,
}));

vi.mock("./tauri", () => ({
  onTerminalOutput: vi.fn(async (listener: (payload: TerminalOutputPayload) => void) => {
    callbacks.output = listener;
    return () => undefined;
  }),
  onTerminalLifecycle: vi.fn(async (listener: (payload: TerminalLifecyclePayload) => void) => {
    callbacks.lifecycle = listener;
    return () => undefined;
  }),
}));

import { getBacklogMetricsForTest, terminalEventBus } from "./terminalEvents";

function encodeOutput(text: string) {
  const bytes = new TextEncoder().encode(text);
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary);
}

describe("terminalEventBus title tracking", () => {
  it("publishes OSC title changes even when no xterm output subscriber is mounted", async () => {
    await terminalEventBus.ensureStarted();
    const titles: Array<[string, string]> = [];
    const unsubscribe = terminalEventBus.subscribeTitle((sessionId, title) => titles.push([sessionId, title]));

    callbacks.output?.({
      sessionId: "backend-background",
      data: encodeOutput("progress\x1b]0;⠋ omo: working\x07more"),
    });
    callbacks.output?.({
      sessionId: "backend-background",
      data: encodeOutput("\x1b]0;✳ omo: done\x07"),
    });

    expect(titles).toEqual([
      ["backend-background", "⠋ omo: working"],
      ["backend-background", "✳ omo: done"],
    ]);

    unsubscribe();
    terminalEventBus.clearSession("backend-background");
  });

  it("deduplicates repeated identical OSC titles", async () => {
    await terminalEventBus.ensureStarted();
    const titles: string[] = [];
    const unsubscribe = terminalEventBus.subscribeTitle((_sessionId, title) => titles.push(title));
    const repeated = encodeOutput("\x1b]2;✋ codex: needs input\x07");

    callbacks.output?.({ sessionId: "backend-dedupe", data: repeated });
    callbacks.output?.({ sessionId: "backend-dedupe", data: repeated });

    expect(titles).toEqual(["✋ codex: needs input"]);

    unsubscribe();
    terminalEventBus.clearSession("backend-dedupe");
  });
});

describe("terminalEventBus backlog buffer", () => {
  it("stores incoming output in chunk array without quadratic concatenation", async () => {
    await terminalEventBus.ensureStarted();
    const sessionId = "backend-chunks";
    const chunkCount = 25;
    const chunkText = "x".repeat(100);

    for (let index = 0; index < chunkCount; index += 1) {
      callbacks.output?.({
        sessionId,
        data: encodeOutput(chunkText),
      });
    }

    const metrics = getBacklogMetricsForTest(sessionId);
    expect(metrics.sessions).toBe(1);
    expect(metrics.chars).toBe(chunkCount * 100);
    // On chunk-ring implementation, chunks must be preserved (>1) rather than collapsed into a single monolithic string
    expect(metrics.chunks).toBeGreaterThan(1);
    expect(metrics.chunks).toBe(chunkCount);

    terminalEventBus.clearSession(sessionId);
  });

  it("bounds total backlog size to MAX_BACKLOG_CHARS and replays latest tail to new subscriber", async () => {
    await terminalEventBus.ensureStarted();
    const sessionId = "backend-overflow";
    const chunkSize = 10000;
    const chunkCount = 60; // 600,000 chars > 512 * 1024 (524,288)
    const tailMarker = "TAIL_SENTINEL_2026";

    for (let index = 0; index < chunkCount; index += 1) {
      const isLast = index === chunkCount - 1;
      const text = isLast
        ? "y".repeat(chunkSize - tailMarker.length) + tailMarker
        : "y".repeat(chunkSize);
      callbacks.output?.({
        sessionId,
        data: encodeOutput(text),
      });
    }

    let replayed = "";
    const unsubscribe = terminalEventBus.subscribeOutput(sessionId, (text) => {
      replayed = text;
    }, true);

    const maxBacklog = 512 * 1024;
    expect(replayed.length).toBe(maxBacklog);
    expect(replayed.endsWith(tailMarker)).toBe(true);

    const metrics = getBacklogMetricsForTest(sessionId);
    expect(metrics.chars).toBe(maxBacklog);
    expect(metrics.chunks).toBeGreaterThan(1);

    unsubscribe();
    terminalEventBus.clearSession(sessionId);
  });

  it("clears session backlog and listeners on clearSession", async () => {
    await terminalEventBus.ensureStarted();
    const sessionId = "backend-clear";
    callbacks.output?.({
      sessionId,
      data: encodeOutput("some initial output"),
    });

    expect(getBacklogMetricsForTest(sessionId).chunks).toBe(1);
    terminalEventBus.clearSession(sessionId);

    expect(getBacklogMetricsForTest(sessionId)).toEqual({
      sessions: 0,
      chunks: 0,
      chars: 0,
    });
  });

  it("replays bounded retained suffix in order and preserves title updates while unsubscribed", async () => {
    await terminalEventBus.ensureStarted();
    const sessionId = "unsubscribed-bounded-replay";
    const titles: Array<[string, string]> = [];
    const unsubscribeTitle = terminalEventBus.subscribeTitle((id, title) => {
      titles.push([id, title]);
    });

    const maxBacklog = 512 * 1024;
    const initialPrefix = "START_OF_STREAM_THAT_SHOULD_BE_DROPPED\n";
    callbacks.output?.({
      sessionId,
      data: encodeOutput(initialPrefix),
    });

    // Send OSC title update while no output renderer is subscribed
    callbacks.output?.({
      sessionId,
      data: encodeOutput("\x1b]0;background task running\x07"),
    });

    // Send large volume exceeding maxBacklog to trigger retention truncation
    const chunkSize = 10000;
    const chunkCount = 60; // 600,000 chars > 512 * 1024 (524,288)
    for (let index = 0; index < chunkCount; index += 1) {
      callbacks.output?.({
        sessionId,
        data: encodeOutput(`chunk-${index.toString().padStart(4, "0")}: ${"a".repeat(chunkSize - 16)}\n`),
      });
    }

    // Send another title update while unsubscribed from output
    callbacks.output?.({
      sessionId,
      data: encodeOutput("\x1b]0;background task complete\x07"),
    });

    // Assert title listener caught both title events despite no output listener being subscribed
    expect(titles).toEqual([
      [sessionId, "background task running"],
      [sessionId, "background task complete"],
    ]);

    // Now subscribe an output listener and verify replay behavior
    const receivedChunks: string[] = [];
    const unsubscribeOutput = terminalEventBus.subscribeOutput(
      sessionId,
      (chunk) => {
        receivedChunks.push(chunk);
      },
      true,
    );

    // Initial replayed chunk must be bounded to MAX_BACKLOG_CHARS and contain the suffix, not the dropped prefix
    expect(receivedChunks).toHaveLength(1);
    const replayedBacklog = receivedChunks[0]!;
    expect(replayedBacklog.length).toBe(maxBacklog);
    expect(replayedBacklog.includes(initialPrefix)).toBe(false);
    expect(replayedBacklog.includes("chunk-0059:")).toBe(true);

    // Emit live output after subscribing
    const liveChunk1 = "LIVE_CHUNK_ALPHA\n";
    const liveChunk2 = "LIVE_CHUNK_BETA\n";
    callbacks.output?.({
      sessionId,
      data: encodeOutput(liveChunk1),
    });
    callbacks.output?.({
      sessionId,
      data: encodeOutput(liveChunk2),
    });

    // Assert retained chunk was received first, followed by live output in exact order
    expect(receivedChunks).toEqual([
      replayedBacklog,
      liveChunk1,
      liveChunk2,
    ]);

    unsubscribeTitle();
    unsubscribeOutput();
    terminalEventBus.clearSession(sessionId);
  });
});

